const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-116.939238, 50.332360]);
  const region = center.buffer(60000); // 60km radius
  const date1 = '2020-12-02';
  const date2 = '2020-12-05';

  // 2. Data Acquisition - MODIS Cloud product
  const modisCol = ee.ImageCollection('MODIS/061/MOD06_L2');

  const col1 = modisCol
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(region);

  const col2 = modisCol
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(region);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Dec 2 Images: ${size1}`);
  console.log(`Dec 5 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get mean cloud fraction for each date
  const img1 = col1.mean().select('Cloud_Fraction');
  const img2 = col2.mean().select('Cloud_Fraction');

  // Check valid pixels
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Cloud_Fraction').getInfo();

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Cloud_Fraction').getInfo();

  console.log(`Dec 2 Valid Pixels: ${count1}`);
  console.log(`Dec 5 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean cloud fraction
  const cloud1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Cloud_Fraction').getInfo();

  const cloud2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Cloud_Fraction').getInfo();

  console.log(`Dec 2 Cloud: ${cloud1?.toFixed(3)}`);
  console.log(`Dec 5 Cloud: ${cloud2?.toFixed(3)}`);

  // Validation
  if (cloud1 === null || cloud2 === null || 
      isNaN(cloud1) || isNaN(cloud2) ||
      cloud1 < 0 || cloud1 > 1 || cloud2 < 0 || cloud2 > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (cloud2 > cloud1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
